import { useState, type FormEvent } from "react";
import { useNavigate } from "react-router";
import { api, checkDateInput, formatDateTime, ValidationError } from "@endgame/appkit";
import { Button, Card, CardContent, CardHeader, CardTitle, FieldError, Input, Label } from "@endgame/appkit/ui";

const WHEN = { min: "2000-01-01T00:00", max: "2099-12-31T23:59" } as const;

/** Add a dive: the form, and beside it the dive as it will read. */
export default function NewDivePage() {
  const navigate = useNavigate();
  const [site, setSite] = useState("");
  const [when, setWhen] = useState("");
  const [errors, setErrors] = useState<Record<string, string[]>>({});

  async function submit(event: FormEvent) {
    event.preventDefault();
    const found: Record<string, string[]> = {};
    if (!site.trim()) found.Site = ["Name the dive site."];
    else if (site.trim().length > 120) found.Site = ["Keep the site to 120 characters."];
    const checked = checkDateInput(when, { ...WHEN, required: true });
    if (checked.error) found.When = [checked.error];
    setErrors(found);
    if (Object.keys(found).length > 0) return;
    try {
      const dive = await api<{ id: string }>("dives", { method: "POST", body: { site, when: checked.date?.toISOString() } });
      navigate(`/dives/${dive.id}`);
    } catch (error) {
      if (error instanceof ValidationError) setErrors(error.errors);
    }
  }

  return (
    <section data-testid="page-new-dive" className="grid grid-cols-1 gap-6 lg:grid-cols-3">
      <Card className="lg:col-span-2">
        <CardHeader>
          <CardTitle>Add a dive</CardTitle>
        </CardHeader>
        <CardContent>
          <form className="flex flex-col gap-4" onSubmit={submit} noValidate>
            <Label htmlFor="site">Dive site</Label>
            <Input
              id="site"
              name="site"
              data-testid="dive-site"
              required
              aria-required="true"
              maxLength={120}
              value={site}
              onChange={(e) => setSite(e.target.value)}
              invalid={!!errors.Site}
              aria-describedby="site-error"
            />
            <FieldError id="site-error">{errors.Site?.[0]}</FieldError>
            <Label htmlFor="when">When</Label>
            <Input
              id="when"
              name="when"
              type="datetime-local"
              data-testid="dive-when"
              min={WHEN.min}
              max={WHEN.max}
              value={when}
              onChange={(e) => setWhen(e.target.value)}
              invalid={!!errors.When}
              aria-describedby="when-error"
            />
            <FieldError id="when-error">{errors.When?.[0]}</FieldError>
            <Button type="submit" data-testid="save-dive">
              Save dive
            </Button>
          </form>
        </CardContent>
      </Card>
      <Card aria-label="How it will read">
        <CardHeader>
          <CardTitle>{site || "Untitled dive"}</CardTitle>
          <p>{formatDateTime(when, { fallback: "No date yet" })}</p>
        </CardHeader>
      </Card>
    </section>
  );
}

