import { fireEvent, render, screen } from "@testing-library/react";
import { MemoryRouter, Route, Routes } from "react-router";
import { BAD_INPUT_TEST, holdsUpAgainstBadInput, jsonResponse } from "@endgame/appkit/testing";
import { describe, expect, it, vi } from "vitest";
import NewDivePage from "./NewDivePage";

const renderPage = () =>
  render(
    <MemoryRouter initialEntries={["/dives/new"]}>
      <Routes>
        <Route path="/dives/new" element={<NewDivePage />} />
        <Route path="/dives/:id" element={<p>opened dive</p>} />
      </Routes>
    </MemoryRouter>,
  );

describe("NewDivePage", () => {
  it("saves a dive and opens it", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(jsonResponse(201, { id: "d1" }));
    renderPage();
    fireEvent.change(screen.getByTestId("dive-site"), { target: { value: "Blue Hole" } });
    fireEvent.change(screen.getByTestId("dive-when"), { target: { value: "2026-12-12T08:00" } });
    fireEvent.click(screen.getByTestId("save-dive"));
    expect(await screen.findByText("opened dive")).toBeTruthy();
  });

  it.each(["dive-site", "dive-when"])(BAD_INPUT_TEST, async (field) => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(jsonResponse(201, { id: "d1" }));
    await holdsUpAgainstBadInput(field, { render: renderPage, page: "page-new-dive", submit: "save-dive" });
  });
});
